    'search'=>['id'=>'reportPotensiDetailSearch','placeholder'=>'Cari detail...'],
    'filters'=>[
        ['id'=>'reportPotensiDetailStatus','label'=>'Status','type'=>'select','width'=>'145px','options'=>[
            'ALL'=>'Semua Status','AMAN'=>'Aman / Lunas','JATUH TEMPO'=>'Jatuh Tempo','FLOW KOLEK'=>'Flow Kolek','MASIH POTENSI'=>'Masih Potensi',
        ]],
        ['id'=>'reportPotensiDetailCommitment','label'=>'Komitmen','type'=>'select','width'=>'135px','options'=>[
